class Solution {
public:
    int maximumRemovals(string s, string p, vector<int>& removable) {
        int n = s.size();
        int m = removable.size();
        int ps = p.size();
        vector<bool> removed(n, false);
        auto check = [&](int k) -> bool {
            for (int i = 0; i < n; i++) removed[i] = false;
            for (int i = 0; i < k; i++) removed[removable[i]] = true;
            int j = 0;
            for (int i = 0; i < n && j < ps; i++) {
                if (!removed[i] && s[i] == p[j]) j++;
            }
            return j == ps;
        };
        int lo = 0, hi = m;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (check(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};
